#!/usr/bin/env python3
"""Curated v2 case-based questions, evidence and engineering reasoning. No network calls.
Source alignment: AI Systems Engineering field manual (08 Nov 2026), 10 domain modules.
Run to regenerate source/scenario-questions.json. Retains all v1 questions and IDs.
"""
import json
from pathlib import Path

out=[]
def q(module, level, topic, term, scenario, prompt, correct, alternatives, rationale, why_not, transfer, evidence=None):
    assert level in (2,3) and len(alternatives)==len(why_not)==3
    idx=sum(x['module']==module and x['level']==level for x in out)+1
    ident=f'{module}-v2-L{level}-{idx:02}'
    options=[correct,*alternatives]
    assert len(set(options))==4, ident
    out.append(dict(id=ident,module=module,level=level,difficulty='applied' if level==2 else 'judgment',
        lesson=topic,term=term,scenario=scenario,question=prompt,options=options,answer=correct,
        explanation=rationale,distractor_notes=dict(zip(alternatives,why_not)),
        learning_note=transfer,hint='Identify what the evidence establishes; separate hypotheses from controlled decisions.',
        evidence=evidence or [],quality='curated',source='Field manual · architecture boundaries, measurement and safe execution'))

# L2: interpret an observed failure or measurement. L3: choose a defensible intervention under constraints.
